import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import { buildSeed } from '../src/data/seed.ts';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

console.log('Generating CivilEdge Supabase seed script from buildSeed()...');

const seed = buildSeed();

let sql = `-- ==============================================================================
-- CivilEdge IAS — Canonical UPSC CSE Seed Data for Option A
-- Auto-generated by scripts/generate-seed.ts
-- ==============================================================================

BEGIN;

`;

// Broadcasts
for (const b of seed.broadcasts) {
  const topics = `{${b.topicsCovered.map((t) => `"${t.replace(/"/g, '""')}"`).join(',')}}`;
  sql += `INSERT INTO public.broadcast_classes (id, title, subject, faculty, faculty_designation, source, stream_url, scheduled_at, duration_minutes, status, description, topics_covered, viewers_count)
VALUES ('${b.id}', '${b.title.replace(/'/g, "''")}', '${b.subject}', '${b.faculty.replace(/'/g, "''")}', '${(b.facultyDesignation || '').replace(/'/g, "''")}', '${b.source}', '${b.streamUrl}', '${b.scheduledAt}', ${b.durationMinutes}, '${b.status}', '${(b.description || '').replace(/'/g, "''")}', '${topics}', ${b.viewersCount || 0})
ON CONFLICT (id) DO NOTHING;\n\n`;
}

// Topics of Day
for (const t of seed.topics) {
  const bullets = `{${t.summaryBullets.map((s) => `"${s.replace(/"/g, '""')}"`).join(',')}}`;
  sql += `INSERT INTO public.topics_of_day (id, title, category, source, publish_date, read_time_minutes, gs_paper, summary_bullets, pdf_brief_name)
VALUES ('${t.id}', '${t.title.replace(/'/g, "''")}', '${t.category}', '${t.source.replace(/'/g, "''")}', '${t.publishDate}', ${t.readTimeMinutes}, '${t.gsPaper}', '${bullets}', '${t.pdfBriefName}')
ON CONFLICT (id) DO NOTHING;\n\n`;
}

// Questions
for (const q of seed.quizQuestions) {
  const optsEn = `{${q.optionsEn.map((o) => `"${o.replace(/"/g, '""')}"`).join(',')}}`;
  const optsHi = `{${q.optionsHi.map((o) => `"${o.replace(/"/g, '""')}"`).join(',')}}`;
  sql += `INSERT INTO public.quiz_questions (id, subject, topic, gs_paper, question_en, question_hi, options_en, options_hi, correct_index, explanation_en, explanation_hi, source_book)
VALUES ('${q.id}', '${q.subject}', '${q.topic.replace(/'/g, "''")}', '${q.gsPaper}', '${q.questionEn.replace(/'/g, "''")}', '${q.questionHi.replace(/'/g, "''")}', '${optsEn}', '${optsHi}', ${q.correctIndex}, '${q.explanationEn.replace(/'/g, "''")}', '${q.explanationHi.replace(/'/g, "''")}', '${q.sourceBook.replace(/'/g, "''")}')
ON CONFLICT (id) DO NOTHING;\n\n`;
}

// Quizzes
for (const qz of seed.quizzes) {
  const qIds = `{${qz.questionIds.join(',')}}`;
  sql += `INSERT INTO public.quizzes (id, title, gs_paper, subject, test_type, duration_minutes, question_ids, is_published)
VALUES ('${qz.id}', '${qz.title.replace(/'/g, "''")}', '${qz.gsPaper}', '${qz.subject}', '${qz.testType}', ${qz.durationMinutes}, '${qIds}', ${qz.isPublished})
ON CONFLICT (id) DO NOTHING;\n\n`;
}

// Mains Questions
for (const m of seed.mainsQuestions) {
  const fwJson = JSON.stringify(m.framework).replace(/'/g, "''");
  sql += `INSERT INTO public.mains_questions (id, title, gs_paper, subject, marks, word_limit, prompt, suggested_time_min, framework, model_answer_snippet, publish_date)
VALUES ('${m.id}', '${m.title.replace(/'/g, "''")}', '${m.gsPaper}', '${m.subject}', ${m.marks}, ${m.wordLimit}, '${m.prompt.replace(/'/g, "''")}', ${m.suggestedTimeMin}, '${fwJson}'::jsonb, '${m.modelAnswerSnippet.replace(/'/g, "''")}', '${m.publishDate}')
ON CONFLICT (id) DO NOTHING;\n\n`;
}

// Resources
for (const r of seed.resources) {
  const topics = `{${r.topicsCovered.map((t) => `"${t.replace(/"/g, '""')}"`).join(',')}}`;
  sql += `INSERT INTO public.resources (id, title, category, gs_paper, format, size_bytes, pages, downloads, rating, author_or_source, summary, topics_covered, is_user_uploaded, moderation_status)
VALUES ('${r.id}', '${r.title.replace(/'/g, "''")}', '${r.category}', '${r.gsPaper}', '${r.format}', ${r.sizeBytes}, ${r.pages || 'NULL'}, ${r.downloads}, ${r.rating}, '${r.authorOrSource.replace(/'/g, "''")}', '${r.summary.replace(/'/g, "''")}', '${topics}', ${r.isUserUploaded}, '${r.moderationStatus}')
ON CONFLICT (id) DO NOTHING;\n\n`;
}

sql += `COMMIT;\n`;

const outDir = path.resolve(__dirname, '../supabase');
if (!fs.existsSync(outDir)) {
  fs.mkdirSync(outDir, { recursive: true });
}
const outPath = path.join(outDir, 'seed.sql');
fs.writeFileSync(outPath, sql, 'utf8');

console.log(`[OK] Generated ${outPath} successfully with ${seed.quizQuestions.length} MCQs, ${seed.quizzes.length} Quizzes, ${seed.mainsQuestions.length} Mains prompts, and ${seed.resources.length} Resources.`);
